// Sandbox is the sole authority over one pod. The pod is created
// immediately, ownerless, and lives until grace past the latest lease, or
// grace past ready if no lease ever arrives. If creation fails it deletes
// whatever it made and fails.
func SandboxChild(ctx workflow.Context, req *SandboxInput, options ...*SandboxChildOptions) error {
	childRun, err := SandboxChildAsync(ctx, req, options...)
	if err != nil {
		return err
	}
	return childRun.Get(ctx)
}

// Sandbox is the sole authority over one pod. The pod is created
// immediately, ownerless, and lives until grace past the latest lease, or
// grace past ready if no lease ever arrives. If creation fails it deletes
// whatever it made and fails.
func SandboxChildAsync(ctx workflow.Context, req *SandboxInput, options ...*SandboxChildOptions) (*SandboxChildRun, error) {
	var o *SandboxChildOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewSandboxChildOptions()
	}
	opts, err := o.Build(ctx, req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing workflow.ChildWorkflowOptions: %w", err)
	}
	ctx = workflow.WithChildOptions(ctx, opts)
	if o.dc != nil {
		ctx = workflow.WithDataConverter(ctx, o.dc)
	}
	return &SandboxChildRun{Future: workflow.ExecuteChildWorkflow(ctx, SandboxWorkflowName, req)}, nil
}

