// SandboxesActivities describes available worker activities
type SandboxesActivities interface {
	// RunTool runs on the pod's sidecar worker, which hands the command to the
	// sandbox container. Callers route each call to the sandbox's own queue,
	// "sandbox-{sandboxId}". The sidecar keeps each finished call's output, so
	// a retry of a call that finished runs nothing.
	RunTool(ctx context.Context, req *RunToolInput) (*RunToolOutput, error)
}

// RegisterSandboxesActivities registers activities with a worker
func RegisterSandboxesActivities(r worker.ActivityRegistry, activities SandboxesActivities) {
	RegisterRunToolActivity(r, activities.RunTool)
}

// RegisterRunToolActivity registers a sandbox.v1.RunTool activity
func RegisterRunToolActivity(r worker.ActivityRegistry, fn func(context.Context, *RunToolInput) (*RunToolOutput, error)) {
	r.RegisterActivityWithOptions(fn, activity.RegisterOptions{
		Name: RunToolActivityName,
	})
}

// RunToolFuture describes a(n) sandbox.v1.RunTool activity execution
type RunToolFuture struct {
	Future workflow.Future
}

// Get blocks on the activity's completion, returning the response
func (f *RunToolFuture) Get(ctx workflow.Context) (*RunToolOutput, error) {
	var resp RunToolOutput
	if err := f.Future.Get(ctx, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

// Select adds the activity's completion to the selector, callback can be nil
func (f *RunToolFuture) Select(sel workflow.Selector, fn func(*RunToolFuture)) workflow.Selector {
	return sel.AddFuture(f.Future, func(workflow.Future) {
		if fn != nil {
			fn(f)
		}
	})
}

// RunTool runs on the pod's sidecar worker, which hands the command to the
// sandbox container. Callers route each call to the sandbox's own queue,
// "sandbox-{sandboxId}". The sidecar keeps each finished call's output, so
// a retry of a call that finished runs nothing.
func RunTool(ctx workflow.Context, req *RunToolInput, options ...*RunToolActivityOptions) (*RunToolOutput, error) {
	return RunToolAsync(ctx, req, options...).Get(ctx)
}

// RunTool runs on the pod's sidecar worker, which hands the command to the
// sandbox container. Callers route each call to the sandbox's own queue,
// "sandbox-{sandboxId}". The sidecar keeps each finished call's output, so
// a retry of a call that finished runs nothing.
func RunToolAsync(ctx workflow.Context, req *RunToolInput, options ...*RunToolActivityOptions) *RunToolFuture {
	var o *RunToolActivityOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewRunToolActivityOptions()
	}
	var err error
	if ctx, err = o.Build(ctx); err != nil {
		errF, errS := workflow.NewFuture(ctx)
		errS.SetError(err)
		return &RunToolFuture{Future: errF}
	}
	activity := RunToolActivityName
	if o.dc != nil {
		ctx = workflow.WithDataConverter(ctx, o.dc)
	}
	future := &RunToolFuture{Future: workflow.ExecuteActivity(ctx, activity, req)}
	return future
}

// RunTool runs on the pod's sidecar worker, which hands the command to the
// sandbox container. Callers route each call to the sandbox's own queue,
// "sandbox-{sandboxId}". The sidecar keeps each finished call's output, so
// a retry of a call that finished runs nothing.
func RunToolLocal(ctx workflow.Context, req *RunToolInput, options ...*RunToolLocalActivityOptions) (*RunToolOutput, error) {
	return RunToolLocalAsync(ctx, req, options...).Get(ctx)
}

// RunTool runs on the pod's sidecar worker, which hands the command to the
// sandbox container. Callers route each call to the sandbox's own queue,
// "sandbox-{sandboxId}". The sidecar keeps each finished call's output, so
// a retry of a call that finished runs nothing.
func RunToolLocalAsync(ctx workflow.Context, req *RunToolInput, options ...*RunToolLocalActivityOptions) *RunToolFuture {
	var o *RunToolLocalActivityOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewRunToolLocalActivityOptions()
	}
	var err error
	if ctx, err = o.Build(ctx); err != nil {
		errF, errS := workflow.NewFuture(ctx)
		errS.SetError(err)
		return &RunToolFuture{Future: errF}
	}
	var activity any
	if o.fn != nil {
		activity = o.fn
	} else {
		activity = RunToolActivityName
	}
	if o.dc != nil {
		ctx = workflow.WithDataConverter(ctx, o.dc)
	}
	future := &RunToolFuture{Future: workflow.ExecuteLocalActivity(ctx, activity, req)}
	return future
}

// RunToolActivityOptions provides configuration for a(n) sandbox.v1.RunTool activity
type RunToolActivityOptions struct {
	options                workflow.ActivityOptions
	retryPolicy            *temporal.RetryPolicy
	scheduleToCloseTimeout *time.Duration
	startToCloseTimeout    *time.Duration
	dc                     converter.DataConverter
	heartbeatTimeout       *time.Duration
	scheduleToStartTimeout *time.Duration
	taskQueue              *string
	waitForCancellation    *bool
}

// NewRunToolActivityOptions initializes a new RunToolActivityOptions value
func NewRunToolActivityOptions() *RunToolActivityOptions {
	return &RunToolActivityOptions{}
}

// Build initializes a workflow.Context with appropriate ActivityOptions values derived from schema defaults and any user-defined overrides
func (o *RunToolActivityOptions) Build(ctx workflow.Context) (workflow.Context, error) {
	opts := o.options
	if v := o.heartbeatTimeout; v != nil {
		opts.HeartbeatTimeout = *v
	}
	if v := o.retryPolicy; v != nil {
		opts.RetryPolicy = v
	} else if opts.RetryPolicy == nil {
		opts.RetryPolicy = &temporal.RetryPolicy{MaximumAttempts: int32(3)}
	}
	if v := o.scheduleToCloseTimeout; v != nil {
		opts.ScheduleToCloseTimeout = *v
	}
	if v := o.scheduleToStartTimeout; v != nil {
		opts.ScheduleToStartTimeout = *v
	} else if opts.ScheduleToStartTimeout == 0 {
		opts.ScheduleToStartTimeout = 60000000000 // 1 minute
	}
	if v := o.startToCloseTimeout; v != nil {
		opts.StartToCloseTimeout = *v
	} else if opts.StartToCloseTimeout == 0 {
		opts.StartToCloseTimeout = 1800000000000 // 30 minutes
	}
	if v := o.taskQueue; v != nil {
		opts.TaskQueue = *v
	} else if opts.TaskQueue == "" {
		opts.TaskQueue = "sandbox"
	}
	if v := o.waitForCancellation; v != nil {
		opts.WaitForCancellation = *v
	}
	return workflow.WithActivityOptions(ctx, opts), nil
}

